import java.util.*;

public class G {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int s = sc.nextInt() - 1;
        long t = sc.nextLong();
        System.out.println(run(n, k, s, t) + 1);
        sc.close();
    }

    static int run(int n, int k, int s, long t) {
        while (t % n != 0) {
            int dir = s < k ? 1 : -1;
            s = (s + n + dir * (int) (t % n)) % n;
            t--;
        }
        t /= n;
        long[] visited = new long[n];
        Arrays.fill(visited, -1);
        for (long left = t; left > 0; left--) {
            if (visited[s] != -1) {
                long cycle = visited[s] - left;
                for (int i = 0; i < n; i++) {
                    if (visited[i] != -1 && visited[i] <= visited[s] && visited[i] % cycle == 0) {
                        return i;
                    }
                }
                throw new AssertionError();
            }
            visited[s] = left;
            for (int i = n - 1; i > 0; i--) {
                if (s < k) {
                    s += i;
                    if (s >= n) s -= n;
                } else {
                    s -= i;
                    if (s < 0) s += n;
                }
            }
        }
        return s;
    }
}
